window.SNOOT_NATIVE_BUNDLE={"modules": {"app.js": "App({globalData:{edition:'local-v1'}});\n", "utils/drawing.js": "const templates={banana:[[.21,.19],[.4,.19],[.41,.32],[.47,.43],[.6,.51],[.75,.5],[.82,.43],[.85,.55],[.79,.67],[.75,.73],[.75,.85],[.64,.86],[.6,.76],[.44,.75],[.4,.86],[.28,.85],[.25,.74],[.2,.63],[.2,.45]],round:[[.28,.3],[.2,.21],[.16,.24],[.2,.41],[.18,.55],[.23,.72],[.31,.77],[.31,.85],[.41,.85],[.44,.77],[.6,.77],[.63,.85],[.74,.85],[.74,.75],[.82,.65],[.83,.44],[.8,.33],[.85,.23],[.8,.2],[.71,.3]],star:[[.5,.13],[.59,.35],[.82,.23],[.73,.47],[.87,.57],[.67,.66],[.66,.85],[.36,.85],[.34,.67],[.13,.58],[.3,.46],[.22,.23],[.42,.35]]};\nfunction clone(v){return JSON.parse(JSON.stringify(v));}\nfunction blank(){return {version:1,strokes:[],color:'#f2d665',fabric:'短毛绒',accessory:'蝴蝶结',muzzle:'#edb8bc',eye:'normal'};}\nfunction useTemplate(name){return (templates[name]||templates.banana).map(p=>({x:p[0],y:p[1]}));}\nfunction valid(d){return !!d&&Array.isArray(d.strokes)&&d.strokes.some(s=>s.length>=3)&&/^#[a-f0-9]{6}$/i.test(d.color||'');}\nfunction bodyPath(ctx,d,w,h){ctx.beginPath();for(const stroke of d.strokes){if(stroke.length<3)continue;const last=stroke[stroke.length-1];ctx.moveTo((last.x+stroke[0].x)*w/2,(last.y+stroke[0].y)*h/2);for(let i=0;i<stroke.length;i++){const next=stroke[(i+1)%stroke.length];ctx.quadraticCurveTo(stroke[i].x*w,stroke[i].y*h,(stroke[i].x+next.x)*w/2,(stroke[i].y+next.y)*h/2);}ctx.closePath();}}\nfunction round(ctx,x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath();}\nfunction render(ctx,d,w,h,options={}){const emotion=options.emotion||'normal',outline=options.outline;ctx.clearRect(0,0,w,h);if(!valid(d))return;ctx.save();if(options.label){ctx.fillStyle='#000000';ctx.font='900 '+Math.round(w*.21)+'px sans-serif';ctx.textAlign='center';ctx.fillText(options.label,w*.5,h*.39,w*.96);}bodyPath(ctx,d,w,h);if(outline){ctx.strokeStyle='#9b8272';ctx.lineWidth=w*.006;ctx.stroke();ctx.restore();return;}ctx.fillStyle=options.form?'#e6dfd1':d.color;ctx.fill();ctx.save();ctx.clip();let seed=1879;function rand(){seed=(seed*16807)%2147483647;return(seed-1)/2147483646;}const count=d.fabric==='长毛绒'?2700:1500;for(let i=0;i<count;i++){const x=rand()*w,y=rand()*h;ctx.strokeStyle=i%2?'rgba(255,255,255,.26)':'rgba(70,45,20,.08)';ctx.lineWidth=w*.0015;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+w*(rand()-.5)*.016,y+w*(d.fabric==='长毛绒'?.013:.004));ctx.stroke();}ctx.restore();\nconst mx=w*(d.face?d.face.x:.43),my=h*(d.face?d.face.y:.59),mw=w*.13,mh=h*.092;ctx.fillStyle=options.form?'#d4c4ad':d.muzzle;ctx.beginPath();ctx.ellipse(mx,my,mw,mh,0,0,Math.PI*2);ctx.fill();ctx.lineCap='round';ctx.strokeStyle='#202020';ctx.lineWidth=w*.011;for(const side of [-1,1]){const ex=mx+side*w*.045,ey=my-h*.027;if(emotion==='normal'){ctx.fillStyle='#202020';ctx.beginPath();ctx.arc(ex,ey,w*.009,0,Math.PI*2);ctx.fill();}else{ctx.beginPath();if(emotion==='no'||emotion==='sad')ctx.arc(ex,ey-h*.008,w*.016,0,Math.PI);else ctx.arc(ex,ey+h*.012,w*.016,Math.PI,Math.PI*2);ctx.stroke();}}\n// The nose, mouth, silhouette, material and accessory are invariant across emotions.\nctx.fillStyle='#171717';ctx.beginPath();ctx.ellipse(mx,my+h*.015,w*.031,h*.019,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#202020';ctx.lineWidth=w*.005;ctx.beginPath();ctx.moveTo(mx,my+h*.028);ctx.lineTo(mx,my+h*.061);ctx.stroke();ctx.fillStyle='rgba(255,255,255,.7)';ctx.beginPath();ctx.ellipse(mx-w*.008,my+h*.008,w*.009,h*.003,0,0,Math.PI*2);ctx.fill();\nif(!options.form){if(d.accessory==='蝴蝶结'){ctx.strokeStyle='#bf3943';ctx.lineWidth=w*.006;const x=w*.32,y=h*.3;ctx.beginPath();ctx.moveTo(x,y);ctx.bezierCurveTo(x-w*.11,y-h*.09,x-w*.11,y+h*.06,x,y);ctx.bezierCurveTo(x+w*.11,y-h*.09,x+w*.11,y+h*.06,x,y);ctx.moveTo(x,y);ctx.lineTo(x-w*.035,y+h*.07);ctx.moveTo(x,y);ctx.lineTo(x+w*.035,y+h*.07);ctx.stroke();}else if(d.accessory==='绒球'){['#b6dce5','#e6abc3','#efdb82'].forEach((color,i)=>{ctx.fillStyle=color;ctx.beginPath();ctx.arc(w*(.35+i*.08),h*.34,w*.024,0,Math.PI*2);ctx.fill();});}else if(d.accessory==='星星'){ctx.fillStyle='#f8e8b5';ctx.beginPath();for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,r=w*(i%2?.017:.04);const x=w*.55+Math.cos(a)*r,y=h*.32+Math.sin(a)*r;i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.closePath();ctx.fill();}}\nif(emotion==='sad'){for(const side of [-1,1]){const x=mx+side*w*.048,y=my+h*.008;ctx.fillStyle='#0066ff';ctx.beginPath();ctx.moveTo(x,y);ctx.bezierCurveTo(x-w*.022,y+h*.027,x-w*.013,y+h*.047,x,y+h*.047);ctx.bezierCurveTo(x+w*.013,y+h*.047,x+w*.022,y+h*.027,x,y);ctx.fill();ctx.fillStyle='white';ctx.beginPath();ctx.arc(x-w*.005,y+h*.027,w*.003,0,Math.PI*2);ctx.fill();}}\nctx.restore();}\nfunction initCanvas(page,selector,size=768){return new Promise((resolve,reject)=>{wx.createSelectorQuery().in(page).select(selector).fields({node:true,size:true}).exec(res=>{const r=res&&res[0];if(!r||!r.node){reject(Error('画布尚未就绪，请重新进入创作页。'));return;}const canvas=r.node;canvas.width=size;canvas.height=size;resolve({canvas,ctx:canvas.getContext('2d'),width:size,height:size,cssWidth:r.width,cssHeight:r.height});});});}\nmodule.exports={blank,valid,render,useTemplate,clone,initCanvas};\n", "utils/files.js": "function persist(tempFilePath,id){return new Promise((resolve,reject)=>{const dest=wx.env.USER_DATA_PATH+'/snoot-'+id+'.png';wx.getFileSystemManager().copyFile({srcPath:tempFilePath,destPath:dest,success:()=>resolve(dest),fail:()=>reject(Error('图片未能保存在本机，请检查可用空间后重试。'))});});}\nfunction discard(paths){for(const filePath of paths)if(filePath&&filePath.startsWith(wx.env.USER_DATA_PATH+'/'))wx.getFileSystemManager().unlink({filePath,fail(){}});}\nfunction exportCanvas(canvas,page){return new Promise((resolve,reject)=>{wx.canvasToTempFilePath({canvas,fileType:'png',destWidth:1024,destHeight:1024,success:r=>resolve(r.tempFilePath),fail:()=>reject(Error('图片导出失败，请重试。'))},page);});}\nfunction album(filePath){return new Promise((resolve,reject)=>wx.saveImageToPhotosAlbum({filePath,success:resolve,fail:()=>reject(Error('未保存到相册；请允许相册权限后重试，也可长按预览图片保存。'))}));}\nmodule.exports={persist,discard,exportCanvas,album};\n", "utils/store.js": "const KEY='snoot-wechat-local-v1';\nfunction empty(){return {version:1,ratings:{},likes:{},members:[],draft:null};}\nfunction load(){try{const s=wx.getStorageSync(KEY);if(s&&s.version===1)return {...empty(),...s};}catch{}return empty();}\nfunction commit(s){try{wx.setStorageSync(KEY,s);}catch{throw Error('本机空间不足，未保存成功。请先导出已有作品后重试。');}return s;}\nfunction rate(id,score){if(!Number.isInteger(score)||score<1||score>5)throw Error('请选择1到5颗心。');const s=load();s.ratings[id]=score;commit(s);return score;}\nfunction like(id){const s=load();s.likes[id]=!s.likes[id];commit(s);return s.likes[id];}\nfunction saveDraft(d){const s=load();s.draft=JSON.parse(JSON.stringify(d));commit(s);}\nfunction list(){return load().members;}\nfunction saveMember(member){if(!member.id||!member.name.trim()||!member.design||!member.front)throw Error('请先完成绘制并给娃娃取名。');const s=load();const exists=s.members.findIndex(m=>m.id===member.id);if(exists>=0)s.members[exists]=member;else s.members.push(member);s.draft=null;commit(s);return member;}\nfunction remove(id){const s=load();const member=s.members.find(m=>m.id===id);s.members=s.members.filter(m=>m.id!==id);commit(s);if(member){const paths=[member.front,...Object.values(member.stickers||{})];paths.forEach(filePath=>{if(filePath&&filePath.startsWith(wx.env.USER_DATA_PATH+'/'))wx.getFileSystemManager().unlink({filePath,fail(){}});});}}\nfunction setStickers(id,stickers){const s=load();const m=s.members.find(m=>m.id===id);if(!m)throw Error('请先将娃娃加入家庭。');m.stickers=stickers;commit(s);return m;}\nfunction newId(){return 'local-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,9);}\nmodule.exports={KEY,load,rate,like,saveDraft,list,saveMember,remove,setStickers,newId};\n", "utils/navigation.js": "const tabs=['home','shop','create','family'];function go(name,id){if(tabs.includes(name))wx.switchTab({url:'/pages/'+name+'/index'});else if(name==='cafe'||name==='stickers')wx.navigateTo({url:'/packages/'+name+'/index'+(id?'?id='+encodeURIComponent(id):'')});else wx.navigateTo({url:'/pages/'+name+'/index'+(id?'?id='+encodeURIComponent(id):'')});}function error(e){wx.showToast({title:e.message||'操作未完成，请重试。',icon:'none',duration:3000});}module.exports={go,error};\n", "packages/stickers/index.js": "const store=require('../../utils/store'),drawing=require('../../utils/drawing'),files=require('../../utils/files'),nav=require('../../utils/navigation');const emotions=[{id:'ok',word:'OK',emotion:'ok'},{id:'no',word:'NO',emotion:'no'},{id:'happy',word:'HAPPY',emotion:'happy'},{id:'sad',word:'SAD',emotion:'sad'}];\nPage({data:{member:null,emotions,status:'正在准备画布…',busy:false,ready:false},onLoad(o){this.member=store.list().find(m=>m.id===o.id);this.setData({member:this.member||null,status:this.member?'正在准备画布…':'请先在创作工坊保存自己的娃娃。'});},async onReady(){if(!this.member)return;try{this.stages={};for(const e of emotions){const stage=await drawing.initCanvas(this,'#sticker-'+e.id,1024);drawing.render(stage.ctx,this.member.design,stage.width,stage.height,{emotion:e.emotion,label:e.word});this.stages[e.id]=stage;}this.setData({ready:true,status:'透明底 · 平面黑字 · 只改变眼睛，SAD加纯蓝塑料泪珠'});}catch(e){this.setData({status:e.message});nav.error(e);}},async build(){if(!this.data.ready)throw Error('画布尚未准备好，请稍后重试。');if(this.member.stickers&&emotions.every(e=>this.member.stickers[e.id]))return this.member.stickers;const created=[];try{const stickers={};for(const e of emotions){const temp=await files.exportCanvas(this.stages[e.id].canvas,this);stickers[e.id]=await files.persist(temp,this.member.id+'-'+e.id);created.push(stickers[e.id]);}this.member=store.setStickers(this.member.id,stickers);return stickers;}catch(e){files.discard(created);throw e;}},async save(e){if(this.data.busy)return;this.setData({busy:true,status:'正在导出透明图片…'});try{const stickers=await this.build();await files.album(stickers[e.currentTarget.dataset.id]);this.setData({status:'已保存到相册。'});wx.showToast({title:'已保存',icon:'success'});}catch(error){this.setData({status:error.message});nav.error(error);}finally{this.setData({busy:false});}},async preview(){if(this.data.busy)return;this.setData({busy:true});try{const s=await this.build();wx.previewImage({urls:emotions.map(e=>s[e.id]),current:s.ok});this.setData({status:'四张透明图片已保存在本机，可逐张保存。'});}catch(e){this.setData({status:e.message});nav.error(e);}finally{this.setData({busy:false});}}});\n", "packages/cafe/index.js": "const members=require('../../data/catalog'),spots=require('./photos'),nav=require('../../utils/navigation');Page({data:{members,spots,memberId:'bnaear',spotId:'photoSpot_06',photos:[],cover:'',message:''},onLoad(){this.refresh();},member(e){this.setData({memberId:e.currentTarget.dataset.id});this.refresh();},spot(e){this.setData({spotId:e.currentTarget.dataset.id});this.refresh();},refresh(){const spot=spots.find(s=>s.id===this.data.spotId),photos=spot.photos.filter(p=>p.dolls.includes(this.data.memberId));this.setData({photos,cover:photos.length?photos[0].src:'',message:photos.length?'这里有 '+photos.length+' 张属于它的照片。':'这个位置还没有属于这位朋友的照片。'});},open(){if(!this.data.photos.length){nav.error(Error('换一个位置，找找它的照片吧。'));return;}wx.previewImage({urls:this.data.photos.map(p=>p.src),current:this.data.photos[0].src});}});\n", "packages/cafe/photos.js": "module.exports=[{\"id\": \"photoSpot_01\", \"name\": \"椅子\", \"photos\": [{\"src\": \"/packages/cafe/assets/mountain-cup-chair.webp\", \"dolls\": [\"mountain-dog\", \"cup-bear\"]}]}, {\"id\": \"photoSpot_02\", \"name\": \"咖啡桌\", \"photos\": [{\"src\": \"/packages/cafe/assets/cup-noodle-table.webp\", \"dolls\": [\"cup-bear\", \"noodle\"]}, {\"src\": \"/assets/cafe/xixi-bnaear-table.webp\", \"dolls\": [\"xixi\", \"bnaear\"]}, {\"src\": \"/packages/cafe/assets/weekend-table.webp\", \"dolls\": [\"weekend\"]}]}, {\"id\": \"photoSpot_03\", \"name\": \"沙发\", \"photos\": [{\"src\": \"/assets/cafe/noodle-xixi-sofa.webp\", \"dolls\": [\"noodle\", \"xixi\"]}, {\"src\": \"/packages/cafe/assets/weekend-xixi-sofa.webp\", \"dolls\": [\"weekend\", \"xixi\"]}]}, {\"id\": \"photoSpot_06\", \"name\": \"展示柜\", \"photos\": [{\"src\": \"/packages/cafe/assets/bnaear.webp\", \"dolls\": [\"bnaear\"]}, {\"src\": \"/packages/cafe/assets/cup-bear.webp\", \"dolls\": [\"cup-bear\"]}, {\"src\": \"/packages/cafe/assets/mountain-dog.webp\", \"dolls\": [\"mountain-dog\"]}, {\"src\": \"/packages/cafe/assets/koala-cabinet.webp\", \"dolls\": [\"koala\"]}, {\"src\": \"/packages/cafe/assets/weekend-cabinet.webp\", \"dolls\": [\"weekend\"]}]}, {\"id\": \"photoSpot_07\", \"name\": \"展示台\", \"photos\": [{\"src\": \"/assets/cafe/mountain-koala-plinth.webp\", \"dolls\": [\"mountain-dog\", \"koala\"]}]}];\n", "data/about.js": "module.exports=[['ABOUT US','一个专门收留奇奇怪怪毛绒小家伙的俱乐部。',['SNOOT CLUB（嘴筒子俱乐部）是一个以原创毛绒玩偶为核心的创意品牌，也是一个充满想象力与偶然性的玩偶创作实验室。','我们喜欢柔软的布料、古怪的造型、不太对称的五官，以及制作过程中意外诞生的小惊喜。在这里，你会遇见各种各样的毛绒朋友：有的圆滚滚，有的长得像香蕉，有的耳朵大得离谱，还有的像某种尚未被发现的小生物。','虽然它们拥有不同的身体、颜色与性格，却都有一个共同的特征——标志性的「嘴筒子」。这个小小的面部符号，让形态各异的玩偶成为同一个俱乐部的成员。']],['OUR PHILOSOPHY','我们不制造一模一样的可爱。',['传统毛绒玩偶通常从一张确定的设计图开始，通过标准化的制作流程尽可能还原最初的形象。而在 SNOOT CLUB，我们更关注角色在制作过程中自然生长的可能性。','布料的纹理、针脚的方向、填充的多少，甚至一次缝歪的耳朵，都可能改变玩偶最终的模样。我们不把这些意外视为需要修正的错误，而是将它们看作创作的一部分。','在不断尝试、组合与制作的过程中，原本普通的材料逐渐拥有表情、身体与性格，最终成为独一无二的小家伙。','我们不急着决定一个玩偶应该长成什么样，而是期待它最终会变成谁。']],['MEET THE SNOOTS','一样的嘴筒子，各有各的古怪。',['SNOOT CLUB 的成员没有统一的身高、体型或穿衣风格。它们可以毛茸茸、软塌塌、方方正正，也可以拥有奇怪的身体比例和出人意料的颜色组合。','每一只玩偶都拥有自己的名字、外形与身份档案。那些看似不完美的小细节，恰恰构成了它们独特的个性。','在俱乐部里，没有两只完全相同的玩偶，每一个小家伙都值得被认识和收藏。']],['MAKE YOUR OWN','下一个俱乐部成员，由你来创造。',['SNOOT CLUB 不仅展示已经诞生的毛绒朋友，也邀请每个人参与它们的创造。','在我们的线上创作工坊，你可以自由选择身体形状、布料材质、颜色与面部表情，通过不同元素的组合，创造属于自己的毛绒角色。','这里没有固定模板，也没有关于可爱的标准答案。我们鼓励大胆的尝试、意想不到的搭配，以及那些不那么完美的创作结果。','或许下一只奇奇怪怪的小家伙，就会从你的想象中诞生。']],['JOIN THE CLUB','Stay Soft. Stay Weird.',['保持柔软，保持古怪。','我们相信，可爱从来不只有一种模样。','那些不够对称的、无法归类的、偶然出现的小细节，也值得被喜欢。','希望每个来到 SNOOT CLUB 的人，都能暂时放下对完美的执着，重新发现动手创造与自由想象的乐趣。','欢迎加入嘴筒子俱乐部，让每一种奇怪，都有自己的可爱。']]];\n", "data/catalog.js": "module.exports=[{\"id\": \"noodle\", \"name\": \"泡面头\", \"en\": \"Noodle Head\", \"likes\": 1286, \"front\": \"/assets/noodle.webp\", \"stock\": \"SOLD OUT · 已售罄\", \"builtin\": true}, {\"id\": \"weekend\", \"name\": \"The Weekend\", \"en\": \"Doll 002\", \"likes\": 967, \"front\": \"/assets/weekend.webp\", \"stock\": \"SOLD OUT · 已售罄\", \"builtin\": true}, {\"id\": \"cup-bear\", \"name\": \"杯子熊\", \"en\": \"Cup Bear\", \"likes\": 1128, \"front\": \"/assets/cup-bear.webp\", \"stock\": \"SOLD OUT · 已售罄\", \"builtin\": true}, {\"id\": \"bnaear\", \"name\": \"Bnaear\", \"en\": \"Bnaear\", \"likes\": 1056, \"front\": \"/assets/bnaear.webp\", \"stock\": \"SOLD OUT · 已售罄\", \"builtin\": true}, {\"id\": \"koala\", \"name\": \"KoalaBear\", \"en\": \"KoalaBear\", \"likes\": 892, \"front\": \"/assets/koala.webp\", \"stock\": \"SOLD OUT · 已售罄\", \"builtin\": true}, {\"id\": \"mountain-dog\", \"name\": \"山狗星扣\", \"en\": \"Mountain Dog\", \"likes\": 836, \"front\": \"/assets/mountain-dog.webp\", \"stock\": \"SOLD OUT · 已售罄\", \"builtin\": true}, {\"id\": \"xixi\", \"name\": \"xixi\", \"en\": \"xixi\", \"likes\": 748, \"front\": \"/assets/xixi.webp\", \"stock\": \"SOLD OUT · 已售罄\", \"builtin\": true}];\n", "pages/home/index.js": "const catalog=require('../../data/catalog');const nav=require('../../utils/navigation');Page({data:{members:catalog.slice(0,3)},go(e){nav.go(e.currentTarget.dataset.page);},detail(e){nav.go('detail',e.currentTarget.dataset.id);}});\n", "pages/shop/index.js": "const catalog=require('../../data/catalog'),store=require('../../utils/store'),nav=require('../../utils/navigation');Page({data:{products:[],filter:'all'},onShow(){this.refresh();},refresh(){const s=store.load();this.setData({products:catalog.filter(m=>this.data.filter==='all'||s.ratings[m.id]).map(m=>({...m,score:s.ratings[m.id]||0,hearts:[1,2,3,4,5].map(n=>({score:n,filled:n<=(s.ratings[m.id]||0),selected:n===s.ratings[m.id]}))}))});},filter(e){this.setData({filter:e.currentTarget.dataset.filter});this.refresh();},rate(e){try{store.rate(e.currentTarget.dataset.id,Number(e.currentTarget.dataset.score));this.refresh();}catch(error){nav.error(error);}},detail(e){nav.go('detail',e.currentTarget.dataset.id);}});\n", "pages/family/index.js": "const catalog=require('../../data/catalog'),store=require('../../utils/store'),nav=require('../../utils/navigation');Page({data:{tab:'popular',members:[],mine:[],count:0},onShow(){this.refresh();},refresh(){const s=store.load(),members=catalog.map(m=>({...m,liked:!!s.likes[m.id],total:m.likes+(s.likes[m.id]?1:0)})).sort((a,b)=>b.total-a.total).map((m,i)=>({...m,rank:String(i+1).padStart(2,'0')}));this.setData({members,mine:s.members.slice().reverse(),count:s.members.length});},tab(e){this.setData({tab:e.currentTarget.dataset.tab});},like(e){try{store.like(e.currentTarget.dataset.id);this.refresh();}catch(error){nav.error(error);}},detail(e){nav.go('detail',e.currentTarget.dataset.id);},create(){nav.go('create');}});\n", "pages/about/index.js": "const sections=require('../../data/about');const nav=require('../../utils/navigation');Page({data:{sections:sections.map(s=>({title:s[0],summary:s[1],paragraphs:s[2]}))},go(){nav.go('create');}});\n", "pages/detail/index.js": "const catalog=require('../../data/catalog'),store=require('../../utils/store'),files=require('../../utils/files'),nav=require('../../utils/navigation');Page({data:{member:null,error:''},onLoad(o){this.id=o.id;},onShow(){const member=catalog.find(m=>m.id===this.id)||store.list().find(m=>m.id===this.id);this.setData({member:member||null});},stickers(){nav.go('stickers',this.id);},preview(){wx.previewImage({urls:[this.data.member.front],current:this.data.member.front});},saveImage(){files.album(this.data.member.front).then(()=>wx.showToast({title:'已保存',icon:'success'})).catch(nav.error);},remove(){wx.showModal({title:'移除此作品？',content:'只删除本地作品和它的表情包，无法撤销。',success:r=>{if(r.confirm){try{store.remove(this.id);wx.navigateBack();}catch(e){nav.error(e);}}}});},cafe(){nav.go('cafe');}});\n", "pages/create/index.js": "const store=require('../../utils/store'),drawing=require('../../utils/drawing'),files=require('../../utils/files'),nav=require('../../utils/navigation');\nconst names=['草稿','白胚','面料','配件','完成'],headings=['画一个奇奇怪怪的轮廓。','给想象一点形状。','摸起来，会是什么感觉？','加一点你的古怪。','你好，小家伙。'];\nPage({data:{step:0,steps:names.map((name,index)=>({name,index})),heading:headings[0],nextName:names[1],fabric:'短毛绒',accessory:'蝴蝶结',color:'#f2d665',fabrics:['短毛绒','长毛绒','羊羔绒'],accessories:['蝴蝶结','绒球','星星','不加配件'],colors:[{value:'#f2d665',name:'浅黄'},{value:'#e7aec3',name:'浅粉'},{value:'#b8dce7',name:'浅蓝'},{value:'#d3bee1',name:'浅紫'},{value:'#e6d7be',name:'奶油白'}],name:'',status:'草稿保存在本机。',error:false,busy:false},onLoad(){const saved=store.load().draft;this.design=drawing.valid(saved)?saved:drawing.blank();this.sync();},onReady(){drawing.initCanvas(this,'#doll-canvas').then(stage=>{this.stage=stage;this.draw();}).catch(nav.error);},onShow(){if(this.committed){this.committed=false;this.design=drawing.blank();this.setData({step:0,name:'',heading:headings[0],nextName:names[1],status:'开始一只新的娃娃。',error:false});this.sync();}if(this.stage)this.draw();},onHide(){this.persistDraft();},onUnload(){this.persistDraft();},sync(){this.setData({fabric:this.design.fabric,accessory:this.design.accessory,color:this.design.color});},persistDraft(){if(!this.design||this.committed)return;try{store.saveDraft(this.design);}catch(e){this.setData({status:e.message,error:true});}},draw(){if(!this.stage)return;const s=this.stage;drawing.render(s.ctx,this.design,s.width,s.height,{outline:this.data.step===0,form:this.data.step===1});},template(e){this.design.strokes=[drawing.useTemplate(e.currentTarget.dataset.name)];this.design.face=null;this.persistDraft();this.draw();},clear(){this.design.strokes=[];this.design.face=null;this.persistDraft();this.draw();},undo(){this.design.strokes.pop();this.persistDraft();this.draw();},position(e){const t=(e.touches&&e.touches[0])||(e.changedTouches&&e.changedTouches[0]);if(!t||!this.stage)return null;return{x:Math.max(0,Math.min(1,t.x/this.stage.cssWidth)),y:Math.max(0,Math.min(1,t.y/this.stage.cssHeight))};},touchStart(e){const point=this.position(e);if(!point)return;if(this.data.step===1){this.design.face={x:point.x,y:point.y};this.draw();return;}if(this.data.step!==0)return;this.stroke=[point];this.design.strokes.push(this.stroke);this.draw();},touchMove(e){if(!this.stroke||this.data.step!==0)return;const point=this.position(e);if(!point)return;const last=this.stroke[this.stroke.length-1];if(Math.hypot(last.x-point.x,last.y-point.y)<.004)return;if(this.stroke.length<3000){this.stroke.push(point);this.draw();}},touchEnd(){this.stroke=null;this.persistDraft();},setStep(e){this.move(Number(e.currentTarget.dataset.step));},next(){this.move(this.data.step+1);},previous(){this.move(this.data.step-1);},move(step){if(this.data.busy)return;if(step>0&&!drawing.valid(this.design)){nav.error(Error('先画出完整轮廓，或选一个起始形状。'));return;}step=Math.max(0,Math.min(4,step));this.setData({step,heading:headings[step],nextName:names[step+1]||''});this.persistDraft();this.draw();},fabric(e){this.design.fabric=e.currentTarget.dataset.value;this.sync();this.persistDraft();this.draw();},color(e){this.design.color=e.currentTarget.dataset.value;this.sync();this.persistDraft();this.draw();},accessory(e){this.design.accessory=e.currentTarget.dataset.value;this.sync();this.persistDraft();this.draw();},name(e){this.setData({name:e.detail.value});},async save(){if(this.data.busy)return;if(!drawing.valid(this.design)){nav.error(Error('请先完成娃娃轮廓。'));return;}const name=this.data.name.trim();if(!name){nav.error(Error('先给小家伙取个名字吧。'));return;}if(!this.stage){nav.error(Error('画布尚未准备好。'));return;}this.setData({busy:true,status:'正在保存图片和制作数据…',error:false});let front;try{drawing.render(this.stage.ctx,this.design,this.stage.width,this.stage.height);const id=store.newId();front=await files.persist(await files.exportCanvas(this.stage.canvas,this),id);store.saveMember({id,name,created:Date.now(),front,design:drawing.clone(this.design)});this.committed=true;this.setData({status:'已保存到本机档案袋。'});wx.showToast({title:'已加入家庭',icon:'success'});nav.go('family');}catch(e){if(front)files.discard([front]);this.setData({status:e.message,error:true});nav.error(e);}finally{this.setData({busy:false});}}});\n"}, "wxml": {"packages/stickers/index.wxml": "<view class=\"screen\" wx:if=\"{{member}}\"><view class=\"eyebrow\">LITTLE EMOTIONS, SAME SOUL.</view><view class=\"heading\">{{member.name}}的表情包</view><view class=\"lead\">同一个小家伙，四种小情绪。</view><view class=\"sticker-grid\" style=\"margin-top:28rpx\"><view class=\"sticker-item\" wx:for=\"{{emotions}}\" wx:key=\"id\"><canvas type=\"2d\" id=\"sticker-{{item.id}}\" class=\"sticker-canvas\"/><button bindtap=\"save\" data-id=\"{{item.id}}\" disabled=\"{{busy||!ready}}\">保存 {{item.word}} ↓</button></view></view><button class=\"primary\" style=\"margin-top:28rpx\" bindtap=\"preview\" disabled=\"{{busy||!ready}}\">{{busy?'正在导出…':'预览完整四张 →'}}</button><view class=\"save-status\">{{status}}</view><view class=\"tiny\">基于你的本机二维设计生成，无需联网。主体、鼻子、嘴筒和配件保持一致。</view></view><view class=\"screen empty\" wx:else=\"\">请先创作并保存一只自己的娃娃。</view>\n", "packages/cafe/index.wxml": "<view class=\"screen cafe-screen\"><view class=\"eyebrow\">A LITTLE PLACE FOR LITTLE THINGS.</view><view class=\"heading\">SNOOT CLUB CAFÉ</view><view class=\"lead\">让小家伙，陪你歇一会儿。</view><button bindtap=\"open\" wx:if=\"{{cover}}\"><image class=\"cafe-cover\" src=\"{{cover}}\" mode=\"aspectFill\"/></button><view class=\"empty\" wx:else=\"\" style=\"margin:30rpx 0\"><view class=\"muted\">这里还没有它的打卡照片。</view></view><view class=\"tool-title\">01 / 选一位毛绒朋友</view><scroll-view scroll-x=\"{{true}}\" style=\"white-space:nowrap\"><view class=\"cafe-list\"><button class=\"cafe-choice {{memberId===item.id?'active':''}}\" wx:for=\"{{members}}\" wx:key=\"id\" data-id=\"{{item.id}}\" bindtap=\"member\"><image src=\"{{item.front}}\" mode=\"aspectFit\"/><text>{{item.name}}</text></button></view></scroll-view><view class=\"tool-title\" style=\"margin-top:26rpx\">02 / 找个喜欢的位置</view><view class=\"pill-row\"><button class=\"pill {{spotId===item.id?'active':''}}\" wx:for=\"{{spots}}\" wx:key=\"id\" data-id=\"{{item.id}}\" bindtap=\"spot\">{{item.name}}</button></view><view class=\"muted\">{{message}}</view><button class=\"primary\" style=\"margin-top:28rpx\" disabled=\"{{!photos.length}}\" bindtap=\"open\">打开这一刻 ↗</button><view class=\"tiny\" style=\"margin-top:22rpx\">本地轻触打卡版。合照里的两位成员都能找到对应照片。</view></view>\n", "pages/home/index.wxml": "<view class=\"screen\"><view class=\"hero\"><view class=\"eyebrow\">A LITTLE CLUB FOR LITTLE SOULS</view><view class=\"hero-title\">SNOOT CLUB</view><view class=\"hero-cn\">嘴筒子俱乐部</view><view class=\"hero-desc\">一样的嘴筒子，<view>不一样的小灵魂。</view></view><image class=\"hero-photo\" src=\"/assets/home-family.webp\" mode=\"aspectFill\"/><button class=\"hero-arrow\" bindtap=\"go\" data-page=\"about\" aria-label=\"品牌故事\">↗</button></view><view class=\"entry-grid\"><button class=\"entry\" bindtap=\"go\" data-page=\"create\"><view class=\"entry-title\">创造一个小家伙</view><view class=\"entry-sub\">MAKE YOUR OWN</view></button><button class=\"entry cafe\" bindtap=\"go\" data-page=\"cafe\"><view class=\"entry-title\">去咖啡店坐坐</view><view class=\"entry-sub\">A LITTLE BREAK</view></button></view><view class=\"section-head\"><view class=\"title\">今天，想认识谁？</view><button class=\"text-button\" bindtap=\"go\" data-page=\"family\">所有成员 ↗</button></view><view class=\"member-row\"><button class=\"member-mini\" wx:for=\"{{members}}\" wx:key=\"id\" data-id=\"{{item.id}}\" bindtap=\"detail\"><image src=\"{{item.front}}\" mode=\"aspectFit\"/><text>{{item.name}}</text></button></view><view class=\"story-link\">一个专门收留奇奇怪怪<view>毛绒小家伙的俱乐部。</view><button class=\"text-button\" bindtap=\"go\" data-page=\"about\">读读我们的故事 →</button></view><view class=\"local-banner\">本地体验版 · 作品保存在这台设备</view></view>\n", "pages/shop/index.wxml": "<view class=\"screen pink\"><view class=\"eyebrow\">SOFT THINGS, LITTLE SOULS.</view><view class=\"heading\">带一点柔软回家。</view><view class=\"lead\">每个小家伙，都有自己的古怪。</view><view class=\"pill-row\"><button class=\"pill {{filter==='all'?'active':''}}\" bindtap=\"filter\" data-filter=\"all\">所有小家伙 · 7</button><button class=\"pill {{filter==='liked'?'active':''}}\" bindtap=\"filter\" data-filter=\"liked\">我喜欢的</button></view><view class=\"product-grid\"><view class=\"product\" wx:for=\"{{products}}\" wx:for-item=\"product\" wx:key=\"id\"><button class=\"product-image\" bindtap=\"detail\" data-id=\"{{product.id}}\"><image class=\"product-image\" src=\"{{product.front}}\" mode=\"aspectFit\"/></button><view class=\"product-name\">{{product.name}}</view><view class=\"stock\">{{product.stock}}</view><view class=\"hearts\"><button class=\"heart-button {{heart.filled?'filled':''}}\" wx:for=\"{{product.hearts}}\" wx:for-item=\"heart\" wx:key=\"score\" data-id=\"{{product.id}}\" data-score=\"{{heart.score}}\" bindtap=\"rate\" aria-label=\"{{heart.score}}颗心\">{{heart.filled?'♥':'♡'}}</button></view><view class=\"rating-label\">{{product.score?'我的评分 '+product.score+' / 5':'点亮小心心'}}</view></view></view><view wx:if=\"{{!products.length}}\" class=\"empty\"><view class=\"muted\">给喜欢的娃娃点亮心心，它就会留在这里。</view></view><view class=\"tiny\" style=\"margin-top:30rpx\">评分仅保存在本机。售罄商品暂未开放购买。</view></view>\n", "pages/family/index.wxml": "<view class=\"patterned\"><image class=\"pattern\" src=\"/assets/checks.png\" mode=\"aspectFill\"/><view class=\"screen\"><view class=\"paper\"><view class=\"eyebrow\">MEET THE SNOOTS</view><view class=\"heading\">各有各的古怪。</view><view class=\"muted\">每一个小家伙，都值得被认识。</view><view class=\"tabs\"><button class=\"{{tab==='popular'?'active':''}}\" bindtap=\"tab\" data-tab=\"popular\">人气榜</button><button class=\"{{tab==='mine'?'active':''}}\" bindtap=\"tab\" data-tab=\"mine\">我的创作 · {{count}}</button></view></view><block wx:if=\"{{tab==='popular'}}\"><view class=\"rank-card\" wx:for=\"{{members}}\" wx:key=\"id\"><text class=\"rank-num\">{{item.rank}}</text><button bindtap=\"detail\" data-id=\"{{item.id}}\"><image class=\"rank-photo\" src=\"{{item.front}}\" mode=\"aspectFit\"/></button><view class=\"rank-info\"><view class=\"rank-name\">{{item.name}}</view><view class=\"rank-en\">{{item.en}}</view></view><button class=\"like-button {{item.liked?'active':''}}\" bindtap=\"like\" data-id=\"{{item.id}}\"><text>{{item.liked?'♥':'♡'}}</text><text>{{item.total}}</text></button></view><view class=\"tiny\">初始人气为示例数据，你的点赞仅保存在本机。</view></block><block wx:else=\"\"><view class=\"rank-card\" wx:for=\"{{mine}}\" wx:key=\"id\"><button data-id=\"{{item.id}}\" bindtap=\"detail\"><image class=\"rank-photo\" src=\"{{item.front}}\" mode=\"aspectFit\"/></button><view class=\"rank-info\"><view class=\"rank-name\">{{item.name}}</view><view class=\"rank-en\">{{item.design.fabric}} · {{item.design.accessory}}</view></view><button class=\"text-button\" bindtap=\"detail\" data-id=\"{{item.id}}\">查看 →</button></view><view class=\"empty\" wx:if=\"{{!mine.length}}\"><image src=\"/assets/weekend.webp\" mode=\"aspectFit\"/><view>给下一位成员留个位置。</view><view class=\"muted\">画下自己的娃娃，保存后就会出现在这里。</view></view><button class=\"primary\" style=\"margin-top:28rpx\" bindtap=\"create\">{{mine.length?'再创造一只 →':'去创作 →'}}</button></block></view></view>\n", "pages/about/index.wxml": "<view class=\"screen\"><image class=\"about-logo\" src=\"/assets/snoot-title.webp\" mode=\"aspectFit\"/><view class=\"about-slogan\">Same Snoot,<view>Different Souls.</view></view><view class=\"muted\">一样的嘴筒子，不一样的小灵魂。</view><view class=\"about-section\" wx:for=\"{{sections}}\" wx:key=\"title\"><view class=\"title\">{{item.title}}</view><view class=\"summary\">{{item.summary}}</view><view class=\"paragraph\" wx:for=\"{{item.paragraphs}}\" wx:for-item=\"paragraph\" wx:key=\"*this\">{{paragraph}}</view></view><button class=\"primary\" bindtap=\"go\">创造你的嘴筒子 →</button></view>\n", "pages/detail/index.wxml": "<view class=\"screen\" wx:if=\"{{member}}\"><view class=\"eyebrow\">SNOOT CLUB MEMBER</view><view class=\"heading\">{{member.name}}</view><view class=\"muted\">{{member.builtin?member.en:'我的本机创作'}}</view><button bindtap=\"preview\"><image class=\"wide-photo\" src=\"{{member.front}}\" mode=\"aspectFit\"/></button><view class=\"lead\">一样的嘴筒子，各有各的古怪。</view><block wx:if=\"{{!member.builtin}}\"><view class=\"design-caption\">{{member.design.fabric}} · {{member.design.accessory}}<view>二维手绘作品 · 本机保存</view></view><button class=\"primary\" style=\"margin-top:28rpx\" bindtap=\"stickers\">获得我的四张表情包 →</button><button class=\"secondary\" style=\"margin-top:20rpx\" bindtap=\"saveImage\">保存作品图片</button><button class=\"danger\" bindtap=\"remove\">删除本机作品</button></block><block wx:else=\"\"><view class=\"stock\" style=\"margin:20rpx 0\">{{member.stock}}</view><button class=\"primary\" bindtap=\"cafe\">和小家伙去咖啡店 →</button></block></view><view wx:else=\"\" class=\"screen empty\"><view class=\"heading\">没有找到这只娃娃。</view><view class=\"muted\">作品只保存在创建它的本机。</view></view>\n", "pages/create/index.wxml": "<view class=\"patterned\"><image class=\"pattern\" src=\"/assets/stripes.png\" mode=\"aspectFill\"/><view class=\"screen\"><view class=\"eyebrow\">MAKE YOUR OWN · 本机创作</view><view class=\"heading\" style=\"font-size:44rpx\">{{heading}}</view><view class=\"steps\"><button wx:for=\"{{steps}}\" wx:key=\"index\" class=\"{{step===item.index?'active':''}}\" bindtap=\"setStep\" data-step=\"{{item.index}}\"><text class=\"number\">{{item.index+1}}</text><text>{{item.name}}</text></button></view><view class=\"drawing-stage\"><canvas id=\"doll-canvas\" type=\"2d\" class=\"drawing-canvas\" catchtouchstart=\"touchStart\" catchtouchmove=\"touchMove\" catchtouchend=\"touchEnd\" catchtouchcancel=\"touchEnd\" disable-scroll=\"{{true}}\"/><view class=\"stage-note\">{{step===0?'画出完整外轮廓，抬手后自动闭合':step===1?'轻点画布，调整嘴筒子的位置':'你的二维毛绒设计 · 不是真实3D模型'}}</view></view><view class=\"stage-toolbar\" wx:if=\"{{step===0}}\"><button bindtap=\"undo\">撤销一笔</button><button bindtap=\"clear\">重画</button></view><view class=\"tools\" wx:if=\"{{step===0}}\"><view class=\"tool-title\">也可以从一个形状开始</view><view class=\"pill-row\"><button class=\"pill\" bindtap=\"template\" data-name=\"banana\">香蕉形</button><button class=\"pill\" bindtap=\"template\" data-name=\"round\">圆圆形</button><button class=\"pill\" bindtap=\"template\" data-name=\"star\">枝枝形</button></view></view><view class=\"tools\" wx:if=\"{{step===1}}\"><view class=\"tool-title\">把嘴筒子放在喜欢的位置</view><view class=\"muted\">轻点上方的白胚，让每只娃娃都有自己的表情位置。</view></view><view class=\"tools\" wx:if=\"{{step===2}}\"><view class=\"tool-title\">面料 · {{fabric}}</view><view class=\"pill-row\"><button wx:for=\"{{fabrics}}\" wx:key=\"*this\" class=\"pill {{fabric===item?'active':''}}\" bindtap=\"fabric\" data-value=\"{{item}}\">{{item}}</button></view><view class=\"tool-title\" style=\"margin-top:26rpx\">选择颜色</view><view class=\"swatches\"><button wx:for=\"{{colors}}\" wx:key=\"value\" class=\"swatch {{color===item.value?'active':''}}\" style=\"background:{{item.value}}\" aria-label=\"{{item.name}}\" bindtap=\"color\" data-value=\"{{item.value}}\"/></view></view><view class=\"tools\" wx:if=\"{{step===3}}\"><view class=\"tool-title\">加一点你的古怪</view><view class=\"pill-row\"><button wx:for=\"{{accessories}}\" wx:key=\"*this\" class=\"pill {{accessory===item?'active':''}}\" bindtap=\"accessory\" data-value=\"{{item}}\">{{item}}</button></view></view><view class=\"tools\" wx:if=\"{{step===4}}\"><view class=\"tool-title\">给小家伙取个名字</view><input id=\"doll-name\" class=\"name-input\" value=\"{{name}}\" placeholder=\"比如：今天不想早起\" maxlength=\"18\" bindinput=\"name\"/><view class=\"tiny\" style=\"margin-top:16rpx\">保存完成后，可在档案袋生成四张表情包。</view></view><view class=\"action-row\"><button wx:if=\"{{step>0}}\" class=\"secondary\" bindtap=\"previous\" disabled=\"{{busy}}\">←</button><button wx:if=\"{{step &lt; 4}}\" class=\"primary\" bindtap=\"next\">下一步 · {{nextName}} →</button><button wx:else=\"\" class=\"primary\" bindtap=\"save\" loading=\"{{busy}}\" disabled=\"{{busy}}\">{{busy?'正在保存…':'加入家庭 →'}}</button></view><view class=\"save-status {{error?'error':''}}\">{{status}}</view><view class=\"tiny\">第一版为本地二维创作。网页3D工坊仍独立保留。</view></view></view>\n"}, "configs": {"app.json": {"pages": ["pages/home/index", "pages/shop/index", "pages/create/index", "pages/family/index", "pages/about/index", "pages/detail/index"], "subPackages": [{"root": "packages/cafe", "pages": ["index"]}, {"root": "packages/stickers", "pages": ["index"]}], "window": {"navigationBarTitleText": "SNOOT CLUB", "navigationBarBackgroundColor": "#fbf8f2", "navigationBarTextStyle": "black", "backgroundColor": "#fbf8f2"}, "tabBar": {"color": "#a08e83", "selectedColor": "#9c647a", "backgroundColor": "#fffcf6", "borderStyle": "white", "list": [{"pagePath": "pages/home/index", "text": "俱乐部", "iconPath": "assets/icons/home-normal.png", "selectedIconPath": "assets/icons/home-active.png"}, {"pagePath": "pages/shop/index", "text": "商店", "iconPath": "assets/icons/shop-normal.png", "selectedIconPath": "assets/icons/shop-active.png"}, {"pagePath": "pages/create/index", "text": "创作", "iconPath": "assets/icons/create-normal.png", "selectedIconPath": "assets/icons/create-active.png"}, {"pagePath": "pages/family/index", "text": "档案袋", "iconPath": "assets/icons/family-normal.png", "selectedIconPath": "assets/icons/family-active.png"}]}, "sitemapLocation": "sitemap.json", "lazyCodeLoading": "requiredComponents"}, "sitemap.json": {"desc": "独立本地体验，不开放页面索引。", "rules": [{"action": "disallow", "page": "*"}]}, "packages/stickers/index.json": {"navigationBarTitleText": "我的表情包", "usingComponents": {}}, "packages/cafe/index.json": {"navigationBarTitleText": "口袋咖啡店", "usingComponents": {}}, "pages/home/index.json": {"navigationBarTitleText": "SNOOT CLUB", "usingComponents": {}}, "pages/shop/index.json": {"navigationBarTitleText": "逛逛商店", "usingComponents": {}}, "pages/family/index.json": {"navigationBarTitleText": "成员档案", "usingComponents": {}}, "pages/about/index.json": {"navigationBarTitleText": "品牌故事", "usingComponents": {}}, "pages/detail/index.json": {"navigationBarTitleText": "认识小家伙", "usingComponents": {}}, "pages/create/index.json": {"navigationBarTitleText": "创作工坊", "usingComponents": {}}}, "css": "page{background:#fbf8f2;color:#41372e;font-family:\"Source Han Sans SC\",\"PingFang SC\",sans-serif;font-weight:300;font-size:26rpx;line-height:1.65}view,text,image,button,input,canvas{box-sizing:border-box}button{font:inherit;font-weight:300;color:inherit;margin:0;padding:0;background:transparent;border-radius:0;line-height:inherit}button::after{border:0}image{display:block;width:100%}.screen{padding:34rpx 36rpx 54rpx;position:relative;z-index:1}.eyebrow{font-size:18rpx;letter-spacing:3rpx;color:#a18d7b;margin-bottom:12rpx}.heading{font-size:52rpx;font-weight:300;line-height:1.35;margin-bottom:18rpx}.lead{font-size:25rpx;line-height:1.9;color:#9d8979}.muted{color:#a18c7e;font-size:22rpx;line-height:1.9}.tiny{font-size:19rpx;color:#a28b7c;line-height:1.9}.primary,.secondary{min-height:88rpx;padding:23rpx 36rpx;border-radius:48rpx;text-align:center;font-size:25rpx;line-height:1.6}.primary{background:#89675b;color:#fffaf2}.secondary{background:#fffcf6;border:1rpx solid #d5c0b2;color:#876c5a}.text-button{font-size:23rpx;color:#a37f73;padding:10rpx 0;text-align:left}.section-head{display:flex;justify-content:space-between;align-items:center;gap:20rpx;margin:40rpx 0 24rpx}.section-head .title{font-size:34rpx}.hero{border-radius:38rpx;background:#f2efeb;overflow:hidden;text-align:center;padding-top:38rpx;position:relative}.hero-title{font-size:65rpx;font-weight:300;letter-spacing:5rpx;line-height:1.35}.hero-cn{font-size:23rpx;letter-spacing:7rpx;margin:10rpx 0 25rpx}.hero-desc{font-size:22rpx;color:#a08a77;line-height:1.8}.hero-photo{height:380rpx;margin-top:10rpx}.hero-arrow{position:absolute;right:25rpx;bottom:23rpx;background:#fffcf4d9;border-radius:50%;width:80rpx;height:80rpx;font-size:40rpx;line-height:80rpx}.entry-grid{display:grid;grid-template-columns:1fr 1fr;gap:24rpx;margin-top:28rpx}.entry{padding:30rpx 26rpx;border-radius:32rpx;background:#eae4ee;text-align:left;min-height:168rpx}.entry.cafe{background:#f5e4d6}.entry-title{font-size:28rpx;margin-bottom:8rpx}.entry-sub{font-size:18rpx;letter-spacing:1rpx;color:#a18b86}.member-row{display:flex;gap:18rpx}.member-mini{flex:1;min-width:0;background:#f1ebe1;padding:14rpx 12rpx 22rpx;border-radius:30rpx;font-size:21rpx;text-align:center}.member-mini image{height:175rpx}.story-link{margin-top:38rpx;padding:30rpx 6rpx;border-top:1rpx solid #e8ded0;font-size:28rpx;line-height:1.8}.pill-row{display:flex;gap:14rpx;margin:26rpx 0;flex-wrap:wrap}.pill{padding:14rpx 26rpx;background:#fffcf6bd;border:1rpx solid #ddc8bb;border-radius:40rpx;font-size:23rpx;min-height:66rpx}.pill.active{background:#a0786b;color:#fffaf3;border-color:#a0786b}.pink{background:#f6dfe5;min-height:100vh}.product-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24rpx 20rpx}.product{background:#fffdf8;border-radius:32rpx;padding:16rpx;min-width:0}.product-image{background:#f2eee6;border-radius:23rpx;height:270rpx;width:100%}.product-name{font-size:24rpx;margin:18rpx 4rpx 10rpx}.stock{font-size:16rpx;color:#fff;background:#997467;border-radius:24rpx;padding:5rpx 13rpx;display:inline-block;line-height:1.5}.hearts{display:flex;margin-top:8rpx}.heart-button{min-width:49rpx;min-height:64rpx;text-align:center;line-height:64rpx;font-size:38rpx;color:#d3b3bb}.heart-button.filled{color:#d17e98}.rating-label{font-size:17rpx;color:#ab8e92;margin-left:4rpx}.paper{background:#fffaf4ed;border-radius:36rpx;padding:30rpx;margin-bottom:26rpx}.patterned{position:relative;min-height:100vh;background:#f9f6ed}.patterned .pattern{position:absolute;inset:0;width:100%;height:100%;opacity:.8}.patterned .screen{background:transparent}.tabs{display:flex;gap:36rpx;margin-top:22rpx}.tabs button{font-size:25rpx;color:#ae9988;padding:8rpx 0;border-bottom:2rpx solid transparent}.tabs .active{color:#876555;border-bottom-color:#9c7969}.rank-card{background:#fffdf8f0;border-radius:29rpx;margin-bottom:20rpx;padding:20rpx;display:flex;align-items:center;gap:18rpx}.rank-num{width:33rpx;color:#c49a8c;font-size:29rpx}.rank-photo{height:143rpx;width:140rpx;flex-shrink:0;background:#f2ece2;border-radius:24rpx}.rank-info{flex:1;min-width:0}.rank-name{font-size:26rpx}.rank-en{font-size:18rpx;color:#ab9584;margin-top:7rpx}.like-button{min-width:97rpx;background:#fff6f8;border:1rpx solid #e8c7d0;border-radius:27rpx;display:flex;flex-direction:column;align-items:center;padding:8rpx;font-size:20rpx;color:#bd7c8e}.like-button text:first-child{font-size:34rpx;line-height:1.2}.like-button.active{background:#f6dce6}.empty{text-align:center;background:#fffaf6;padding:50rpx 35rpx;border-radius:34rpx}.empty image{height:230rpx;width:230rpx;margin:0 auto 20rpx}.empty .primary{margin-top:30rpx}.wide-photo{width:100%;height:560rpx;border-radius:34rpx;background:#f2ede4;margin:20rpx 0}.about-logo{height:185rpx}.about-slogan{font-size:47rpx;line-height:1.5;margin:20rpx 3rpx 30rpx}.about-section{border-top:1rpx solid #e5d9c9;padding:37rpx 4rpx}.about-section .title{font-size:39rpx;letter-spacing:1rpx;margin-bottom:24rpx}.about-section .summary{font-size:27rpx;line-height:1.8;margin-bottom:15rpx}.about-section .paragraph{font-size:24rpx;line-height:2.1;color:#8e7c6b;margin-top:18rpx}.steps{display:flex;justify-content:space-between;padding:16rpx 20rpx;background:#fffaf3d9;border-radius:28rpx;margin:26rpx 0}.steps button{font-size:20rpx;color:#b4a08f;display:flex;flex-direction:column;align-items:center;gap:6rpx}.steps .number{background:#ece5dc;border-radius:50%;width:45rpx;height:45rpx;line-height:45rpx;text-align:center;font-size:20rpx}.steps .active{color:#8c6674}.steps .active .number{background:#e9cbd6;color:#8a5b6d}.drawing-stage{background:#fffcf8;border-radius:36rpx;overflow:hidden;position:relative;width:100%;height:678rpx}.drawing-canvas{width:100%;height:100%;display:block}.stage-note{position:absolute;bottom:14rpx;left:14rpx;right:14rpx;text-align:center;pointer-events:none;color:#b19a88;font-size:19rpx}.stage-toolbar{display:flex;justify-content:flex-end;gap:18rpx;margin:10rpx 0}.stage-toolbar button{font-size:22rpx;color:#9f7c68;min-height:60rpx;padding:10rpx}.tools{padding:28rpx;border-radius:30rpx;background:#fffaf4ed;margin:24rpx 0}.tool-title{font-size:25rpx;margin-bottom:18rpx}.tools .pill-row{margin:0}.swatches{display:flex;gap:21rpx;margin-top:15rpx}.swatch{width:62rpx;height:62rpx;border-radius:50%;border:6rpx solid white;box-shadow:0 0 0 1rpx #d8cab9}.swatch.active{box-shadow:0 0 0 3rpx #aa8394}.action-row{display:flex;gap:20rpx}.action-row .primary{flex:1}.name-input{border:1rpx solid #d9c5b4;background:#fffdfa;border-radius:21rpx;width:100%;height:88rpx;padding:16rpx 22rpx;font-size:30rpx}.save-status{padding:15rpx 0;font-size:21rpx;color:#a48f7c;line-height:1.8}.save-status.error{color:#aa4e52}.design-caption{margin-top:22rpx;font-size:21rpx;color:#9f8874;line-height:1.9}.danger{color:#b66e70;font-size:23rpx;padding:20rpx 10rpx}.cafe-screen{background:#eee4d6;min-height:100vh}.cafe-cover{height:500rpx;border-radius:32rpx;margin:30rpx 0 24rpx}.cafe-list{display:flex;gap:16rpx;white-space:nowrap;padding-bottom:12rpx}.cafe-choice{display:inline-flex;flex-direction:column;align-items:center;flex-shrink:0;background:#fff7eb;border-radius:25rpx;border:1rpx solid transparent;padding:12rpx;font-size:19rpx;min-width:145rpx}.cafe-choice.active{border-color:#bc9584}.cafe-choice image{height:125rpx;width:125rpx}.sticker-grid{display:grid;grid-template-columns:1fr 1fr;gap:24rpx}.sticker-item{padding:12rpx;border-radius:28rpx;background:#fffdf8;border:1rpx solid #e8dacf}.sticker-canvas{width:100%;height:290rpx;display:block}.sticker-item button{margin:8rpx 0;font-size:22rpx;color:#9e7d6a;min-height:60rpx}.footer-space{height:30rpx}.local-banner{margin:28rpx 0 0;padding:18rpx 23rpx;background:#f3ebe2;border-radius:20rpx;font-size:20rpx;color:#9c8370;line-height:1.8}\n"};
